def require(path, label):
    path = pathlib.Path(path)
    if not path.exists():
        raise FileNotFoundError(f"Missing {label}: {path}")
    return path


def locate_unique(filename):
    matches = [path for path in INPUT_ROOT.rglob(filename) if "checkpoints" in path.parts]
    if not matches:
        raise FileNotFoundError(
            f"Could not find {filename} below {INPUT_ROOT}. Attach the Models dataset containing sam-base and sam-tiny."
        )
    if len(matches) > 1:
        print(f"Multiple {filename} matches found; using {matches[0]}")
    return matches[0]


def locate_weights(checkpoint):
    model_root = checkpoint.parent.parent
    expected = model_root / "checkpoints_hybrid_attention_focal"
    if expected.exists():
        return expected
    matches = [
        path.parent.parent
        for path in model_root.rglob("adapter_model.safetensors")
        if path.parent.name == "hybrid_sam2_backbone"
    ]
    if not matches:
        raise FileNotFoundError(f"Could not locate hybrid trained weights below {model_root}")
    return matches[0]


require(VAL_IMAGES, "validation images")
require(VAL_MASKS, "validation masks")
BASE_CKPT = locate_unique("sam2_hiera_base_plus.pt")
TINY_CKPT = locate_unique("sam2_hiera_tiny.pt")
BASE_WEIGHTS = locate_weights(BASE_CKPT)
