def ensure_package(import_name, pip_name=None):
    pip_name = pip_name or import_name
    try:
        __import__(import_name)
        return
    except Exception:
        pass
    commands = [
        [sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", pip_name],
        [sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", "--no-deps", pip_name],
    ]
    last_error = None
    for command in commands:
        try:
            subprocess.check_call(command)
            __import__(import_name)
            return
        except Exception as exc:
            last_error = exc
    raise RuntimeError(f"Could not install/import {pip_name}: {last_error}")


def ensure_hydra_stack():
    try:
        import hydra  # noqa: F401
        import omegaconf  # noqa: F401
        return
    except Exception:
        pass
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", "PyYAML"])
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", "antlr4-python3-runtime==4.9.3"])
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", "--no-deps", "omegaconf==2.3.0"])
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir", "--no-deps", "hydra-core==1.3.2"])

