def run_command(command):
    print("Running:", " ".join(map(str, command)))
    subprocess.check_call(list(map(str, command)))


def normalize_model(model_size, checkpoint, weights, run_dir, model_cfg):
    if not (run_dir / "config.json").exists():
        run_command([
            sys.executable, RUNNER_PATH, "import-existing",
            "--sam2-repo", SAM2_DIR,
            "--model-size", model_size,
            "--model-cfg", model_cfg,
            "--checkpoint", checkpoint,
            "--variant", "full",
            "--weights-dir", weights,
            "--out-dir", run_dir,
            "--symlink",
        ])
    return run_dir


